"""v0 에이전트 ― 질문 하나 → 답변 하나.

의도적으로 단순하다. 임베딩·벡터DB 없이 **SQL + 규칙 검색**만으로 end-to-end 를 세운다.
목적은 성능이 아니라 "돌아가는 것"이고, 여기가 앞으로 점수를 재는 기준선이 된다.

흐름
    질문 → ① 기업 특정(모호하면 역질문) → ② 연도·유형 추출
         → ③ SQL 로 근거 후보 조회 → ④ HCX 로 답변 생성 → ⑤ 근거 공시 표기
"""
