# 자기주식 등에서 금액 외에 자주 묻는 raw 필드 (평가 CE군: '예정 주식수' 미검출 실측)
# ★ 2026-08-15, 20배치 블라인드 실측으로 확정된 결함.
#
#   `raw_te` 에 실제로 값이 들어 있는 ACODE 는 **661종**인데, 아래 목록은 **7종**만
#   컨텍스트로 내보내고 있었다 — **1.1%**. 나머지 654종은 파서가 멀쩡히 뽑아 놓고
#   답변 경로에서 통째로 버려졌다. CLAUDE.md 가 「미확인 ACODE 는 raw_te 에 보존돼 있어
#   데이터 유실은 없다」고 적어 둔 그 데이터가 **한 번도 답변에 쓰이지 않고 있었다.**
#
#   증상(20배치 248문항 · 전부 블라인드):
#       유형 층 0.638 · 섹션 층 0.340 · 0.300(=근거는 찾고 값은 못 냄)이 14개 축에서 반복
#       ★ 대량보유 171종 중 노출 0 · 회사합병 28종 중 0 · 신탁계약 64종 중 0
#
#   그래서 **하드코딩 목록을 버리고** 「값이 있는 필드는 전부 싣되 예산 안에서」로 바꾼다.
#   라벨은 파서가 이미 갖고 있는 `ACODE_MAP` 을 재사용한다(없으면 코드 그대로 표기).
RAW_EXPOSE_BUDGET = 24          # 행당 최대 필드 수 (실측: 중앙 22 · 90%tile 85 · 최대 116)
RAW_VALUE_CAP = 400             # 필드 값 1개의 최대 길이
RAW_CHAR_BUDGET = 3000          # 행당 총 글자 예산
# 개수만으로 자르면 서술형 유형이 잘린다. 회사합병 MGR_EFT 는 493자, 투자판단 본문은
# 그보다 길다 — 90자 컷은 그 답을 **문장 중간에서** 끊어버렸다. 반대로 대량보유는
# 짧은 필드가 100개 넘게 온다. 그래서 «개수 상한 + 글자 예산» 두 가지로 자른다.

# 이미 전용 줄로 나가는 값 — 중복 노출하지 않는다.
# CRP_NM 은 빼지 않는다: holding 에서 이 값은 **발행회사의 공시상 법인명**(삼성이앤에이(주))이라
# manifest 의 통용명(삼성E&A)과 다르고, "공시 내용"을 묻는 질문의 답 재료다.
_RAW_SKIP = {"SEQ_NO", "CRP_CD", "RPT_NO"}

# 개인정보 · 답에 쓸 일이 없는 사무 필드. 예산 24칸을 이런 게 6~8칸씩 먹고 있었다.
# (실측: 대량보유 상위 노출 20종 중 RSP_MAN·RSP_MAN_PHN2·RSP_MAN_EML·IFR_ID 등 7종)
_RAW_NOISE_LABEL = ("생년월일", "전화번호", "이메일", "팩스", "담당자", "연락처",
                    "사업자등록번호", "직위", "부서")
_RAW_NOISE_CODE = ("RSP_MAN", "IFR_ID", "IFR_ADR", "ADR2", "SPC_ID")


@functools.lru_cache(maxsize=1)
def _acode_labels() -> tuple[dict, dict, dict]:
    """라벨 사전 3종: (유형,코드) 채굴 · 코드 폴백 · 손으로 확인한 ACODE_MAP.

    채굴 사전은 `scripts/mine_acode_labels.py` 가 원문 표를 격자로 복원해 만든다
    (ROWSPAN/COLSPAN 을 지켜 행 라벨 + 열 머리글을 붙인다). 1,501종.
    이게 없으면 모델은 `CLN_PRC_PRE` 같은 코드명을 그대로 받는다 — 실측으로,
    값이 컨텍스트에 있는데도 "계약금액은 제공되지 않았습니다"라고 답했다.
    """
    mined, fb, hand = {}, {}, {}
    parse_dir = Path(__file__).resolve().parents[1] / "parse"
    try:
        sys.path.insert(0, str(parse_dir))
        import dart_xml                                   # noqa: PLC0415
        hand = {k: v for k, v in getattr(dart_xml, "ACODE_MAP", {}).items()
                if isinstance(v, str)}
    except Exception:                                     # noqa: BLE001
        pass
    # ★ 2026-08-17: 이 임포트가 **모든 실행 경로에서 조용히 실패하고 있었다.**
    #   진입점(run_eval·run_server·ask·test_answer_guards)은 전부 `src/gongsi/agent`
    #   만 sys.path 에 넣는다. `gongsi` 패키지 경로가 없으니 ImportError 가 나고,
    #   아래 `except` 가 그걸 삼켜 채굴 1,512종 + 폴백 661종이 통째로 사라졌다.
    #   그 결과 모델은 `SPL_DPT:` 같은 **코드명**을 받았고, 문항은 채굴 라벨로
    #   물었으므로(생성기만 `src` 를 넣는다) 유형 층이 조용히 깎였다.
    #   → 패키지 경로를 여기서 직접 보장하고, 그래도 안 되면 파일로 직접 읽는다.
    for cand in (str(parse_dir.parents[1]), str(parse_dir)):   # …/src, …/src/gongsi/parse
        if cand not in sys.path:
            sys.path.insert(0, cand)
    try:
        from gongsi.parse.acode_labels import (           # noqa: PLC0415
            MINED_FALLBACK, MINED_LABELS)
        mined, fb = MINED_LABELS, MINED_FALLBACK
    except Exception:                                     # noqa: BLE001
        try:
            import acode_labels                           # noqa: PLC0415
            mined, fb = acode_labels.MINED_LABELS, acode_labels.MINED_FALLBACK
        except Exception:                                 # noqa: BLE001
            pass
    # 조용히 틀리지 않는다 (CLAUDE.md 규칙 2·함정 23). 없으면 «없다»고 말한다.
    missing = [n for n, d in (("채굴", mined), ("폴백", fb), ("수기", hand)) if not d]
    if missing:
        print(f"[경고] ACODE 라벨 사전 {'·'.join(missing)} 을(를) 못 읽었다 "
              f"— 근거에 코드명이 그대로 나간다", file=sys.stderr)
    return mined, fb, hand


def _label_of(code: str, event_type: str) -> str:
    """유형별 채굴 라벨 → 손으로 확인한 사전 → 코드 전역 폴백 → 코드명.

    폴백을 손 사전보다 뒤에 두는 이유: 폴백은 **다른 유형에서의 최빈 라벨**이라
    유형이 다르면 오해를 부른다. 실측 — 대량보유의 CRP_NM 은 발행회사명인데
    폴백이 「기업집단명 회사명」을 붙였고, 모델은 그 줄을 답에서 통째로 버렸다.
    """
    mined, fb, hand = _acode_labels()
    return mined.get((event_type, code)) or hand.get(code) or fb.get(code) or code


def _is_noise(code: str, label: str) -> bool:
    return (any(code.startswith(p) for p in _RAW_NOISE_CODE)
            or any(w in label for w in _RAW_NOISE_LABEL))


def _spaced_quoted_terms(question: str) -> list[str]:
    """「본 점 소 재 지」처럼 **자간 공백** 표기로 인용된 라벨(정기공시 표지 표의 실물 표기).
    한 글자 토막들이라 `[가-힣]{2,}` 토큰화에서 통째로 사라진다(실측 NT-115 —
    gold 가 ctx 0회). 원문도 같은 표기이므로 **인용구 그대로**가 가장 정확한 검색어다.
    다른 문서가 접어 쓴 경우를 위해 접은 형태도 함께 준다."""
    out: list[str] = []
    for g in _QUOTED.findall(question or ""):
        inner = g.strip()
        if re.fullmatch(r"[가-힣](?:\s+[가-힣]){2,}", inner):
            out += [inner, re.sub(r"\s+", "", inner)]
    return out


def _pinned_labels(question: str) -> list[str]:
    """질문이 「」로 지목한 항목명. 공백·중점을 지운 비교용 형태로."""
    return [re.sub(r"[\s·ㆍ]", "", g) for g in _QUOTED.findall(question or "")]


def raw_fields(raw: str | None, event_type: str = "",
               question: str = "", allow_empty: bool = False,
               known_labels: set | None = None) -> list[tuple[str, str]]:
    """`raw_te` 에서 «값이 있는» 필드를 (표시명, 값) 목록으로. 예산 안에서 전부.

    ★ 2026-08-17 실측 (R23 B238-005) — **질문이 지목한 항목이 예산에 잘렸다.**

        Q     한화솔루션이 … 공시에서 「**발행 대상자명**」 항목의 값은?
        DB    ISSU_NM = '더세운서울제이차 주식회사'          ← 있다
        컨텍스트  «더세운» 0회 · «발행 대상자» 0회             ← 한 글자도 안 실렸다
        A     「확인되지 않습니다」                          ← 제품은 정직했다. 회수가 잃은 것이다

      원인은 순수한 자리다툼이다. 이 공시의 `raw_te` 는 37개 필드인데
      `RAW_CHAR_BUDGET`(3,000자)이 **13번째**에서 소진되고 `ISSU_NM` 은 **34번째**다.

      이 프로젝트가 두 번 세운 원칙이 있다 — **질문이 지목한 것은 라우팅·예산과
      무관하게 가져온다** (고친 것 #3 섹션 지목 · #4 지목 회수).
      섹션에는 `section_label_pin()` 으로 들어가 있는데 **이벤트 raw 필드에는
      안 옮겨져 있었다.** 함정 23·24, M-32 ②, M-33 과 같은 병이다.
      → 지목된 항목을 **맨 앞으로 올리고 예산에서 면제한다.**
    """
    try:
        blob = (json.loads(raw) or {}) if raw else {}
    except (json.JSONDecodeError, TypeError):
        return []
    te = dict(blob.get("raw_te") or {})
    # ★ 2026-08-17 M-44 (제3자 홀드아웃 T3-002) — **날짜 항목이 통째로 안 실리고 있었다.**
    #   함정 8 이 「날짜는 `<TU>` 의 AUNITVALUE 에 YYYYMMDD 로 있다」인데, 이 함수는
    #   `raw_te` 만 읽었다. 그래서 「무상증자 **신주배정기준일**」(ALL_BS_DT=20250610)이
    #   근거에 한 글자도 없었고 답은 「확인되지 않습니다」였다 — 값은 DB 안에 있었다.
    #   TE 를 먼저 두고 TU 를 뒤에 붙인다(예산 순서 유지). 사람이 읽는 꼴로도 함께 적는다.
    for code, val in (blob.get("raw_tu") or {}).items():
        if code in te:
            continue
        v = str(val or "").strip()
        if re.fullmatch(r"\d{8}", v):
            te[code] = f"{v[:4]}년 {v[4:6]}월 {v[6:]}일 ({v})"
        elif v and v != "-":
            te[code] = v
    # ★ 2026-08-18 (M-49) — **거래소 이벤트의 raw 는 `raw_te` 가 아니라 최상위 키다.**
    #   `exchange_html.py` 가 라벨 기반으로 뽑아 `{"구분":…, "유보사유":…}` 로 넣는데
    #   이 함수는 `raw_te`/`raw_tu` 만 읽어서 **1,172건의 필드가 통째로 컨텍스트에
    #   안 실리고 있었다** (유보사유는 값이 있는 것만 120건).
    #   실측 T3-012: `유보사유: 경영상 비밀유지` 가 DB 에 있는데 답변은 「확인되지
    #   않습니다」만 하고 **왜 없는지를 말하지 못했다** — 평가지표 7(정보한계 대응)이
    #   바로 그것을 본다. 또 하나의 «한쪽에만 있는 처방»이다 (함정 23 계열).
    #   ★ 다만 **지금 여는 것은 `유보사유` 하나다.** 전부 열면 회귀 풀 400 표본에서
    #     컨텍스트가 **168건(42%)** 바뀐다 — 그 크기의 변화는 점수로 재고 나서 넣어야 한다.
    #     특히 `최근매출액`(9,359,005,981,309)은 T3-012 의 `must_not` 값 그 자체라
    #     「계약금액」 자리에 들어앉을 경쟁자다 (M-48 「더 준 것이 밀어낸다」).
    #     나머지(구분·최근매출액·대규모법인·지역·자기자본)는 **재료로 남겨 둔다** —
    #     결함을 실측한 뒤에 연다.
    for code in ("유보사유",):
        val = blob.get(code)
        if code not in te and isinstance(val, str) and val.strip() not in ("", "-"):
            te[code] = val.strip()
    # ★ 2026-08-30 (NT-036/038 실측) — 위에서 «재료로 남겨 둔» 키를 **질문이 그 라벨을
    #   직접 쓸 때만** 연다 (함정 57 «쓸 때 게이트»). 「최근매출액(원)은 얼마인가」를
    #   묻는데 키가 닫혀 있어 0.30 두 건 — M-49 의 경쟁자 우려는 «전부 열 때» 이야기다.
    _qflat_raw = re.sub(r"[\s·ㆍ()원]", "", question or "")
    for code in ("최근매출액", "구분", "대규모법인", "지역", "자기자본"):
        val = blob.get(code)
        if (code not in te and isinstance(val, (str, int, float))
                and str(val).strip() not in ("", "-") and code in _qflat_raw):
            _v = str(val).strip()          # raw 의 금액은 JSON 정수로도 온다
            # 콤마 없는 원시 정수(«3163343614791»)는 모델이 못 읽는다(M-57 그 병) —
            # 콤마 + 한글 표기로 정규화해 싣는다.
            if re.fullmatch(r"\d{7,}", _v):
                _v = f"{int(_v):,} ({kr_amount(int(_v))})"
            te[code] = _v
    pins = _pinned_labels(question)
    # ★ 2026-08-19 (M-97) — **질문은 항목명을 「」 없이 그냥 쓴다.**
    #   실측 H6-036: 「… 그리고 **보유목적**은?」 인데 `PUR_OWN`(=단순투자)이 예산에 잘려
    #   컨텍스트에 **0회**였다. 값은 DB 에 있었다 (함정 23 계열 — 한쪽에만 있는 처방).
    #   ★ 낱말이 라벨에 «들어 있기만» 하면 안 된다 — 400표본에서 58건 발화하는데
    #     「보고서」·「사채의」 같은 흔한 말이 **직전 보고서(BMT, 함정 22)** 를 못 박는다.
    #     지목이 틀리면 없느니만 못하다(함정 41).
    #   → **그 문서 안에서 라벨 «하나»만 가리키는 낱말**만 지목으로 본다.
    #     (실측: 라벨 1개 조건 = 발화 11/400 · 2개 = 24/400 · 무조건 = 58/400.
    #      H6-036 의 「보유목적」은 1개, 「보유비율」은 6개라 지목이 안 된다 — 옳다.)
    _labs = {c: re.sub(r"[\s·ㆍ]", "", _label_of(c, event_type)) for c in te}
    _labs = {c: l for c, l in _labs.items() if l and l != c}
    #   ★ 조사를 떼고도 본다 — 질문은 「보유목적**은**」이라고 쓴다. 안 떼면 라벨
    #     「보유목적 요약정보」와 한 글자도 안 맞는다(함정 31 을 내 처방에서 또 밟았다).
    _qtoks = set()
    for _t in re.findall(r"[가-힣]{3,}", question or ""):
        if _t in _STOP:
            continue
        _qtoks.add(_t)
        _b = _strip_particle(_t)
        if _b != _t and len(_b) >= 3 and _b not in _STOP:
            _qtoks.add(_b)
    for _t in _qtoks:
        _hit = [l for l in _labs.values() if _t in l]
        if len(_hit) == 1:
            pins.append(_hit[0])
    # ★ 2026-08-30 (NT-097) — 대량보유에는 «관계» 라벨이 **둘** 있고 holding 1,083건
    #   **전부**가 둘을 함께 가지며 **989건(91.3%)에서 값이 다르다**:
    #     FLT_CRP_RLT 발행회사와의 관계(주주) ↔ IFR_RLT 보고자와의구체적 관계(기타)
    #   질문의 「**보고자**와 **발행회사**의 관계」는 두 라벨에 걸쳐 있어 위 «유일 지목»
    #   규칙으로는 못 가른다(라벨 2개가 걸린다). 질문이 「발행회사」를 말하면 그쪽이다.
    if re.search(r"발행\s*회사", question or "") and "관계" in (question or ""):
        _fl = _labs.get("FLT_CRP_RLT")
        if _fl:
            pins.append(_fl)
    # ★ 2026-09-01 (R42 · R10-027) — 「보고구분」은 RPT_DST1/RPT_DST2 **두 코드가 같은
    #   라벨**이라 위 «유일 지목» 규칙이 원리적으로 못 열고(len(_hit)==2), raw_tu 라
    #   예산 24칸에서도 밀린다. 신규/변동·연명 여부가 그 칸에만 있는데 제품은
    #   「확인되지 않습니다」라고 답했다. 질문이 그 낱말을 직접 쓸 때만 지목한다
    #   (NT-097 «관계» 분기와 같은 꼴 — 중복 라벨은 전용 분기로 연다).
    if "보고구분" in (question or "") and any(l == "보고구분" for l in _labs.values()):
        pins.append("보고구분")
    # ★ 2026-08-30 (R6N-067) — **채굴 라벨이 틀린 자리**다. `HLD_OBJ_DTL` 의 채굴 라벨이
    #   「최대주주(법인 대표자)」로 붙어 있는데, 원문에서 그 코드 바로 앞은 「**4. 보유목적**」
    #   이다(격자 복원이 행 라벨을 잘못 집었다). 값이 있는 문서가 **607/1,083(56%)**이고
    #   「보유목적 요약정보」(경영권 영향)만 실려 **세부 내용이 통째로 빠졌다**
    #   (실측 R6N-067: 「에이치엠엠(주) **경쟁력 제고 지원**」이 DB 에 있는데 0.65).
    #   → 질문이 보유목적을 물으면 지목하고, **표시명을 원문 라벨로 바로잡는다.**
    #     (함정 21 은 「사전을 손으로 채우지 마라」이지 「채굴이 틀려도 두라」가 아니다 —
    #      원문 대조로 확인한 정정이다.)
    # ★ 심문 10차 — 1판의 `pins.append(_od)` 는 **죽은 줄이고 값도 틀렸다**(`_od` 는 여전히
    #   채굴 라벨 「최대주주(법인 대표자)」). 아래 전용 분기가 지목을 따로 계산하므로 지운다.
    #   그리고 게이트가 원문을 봐서 「**보유목적 변경**」이 «인용된» 문항 17건이 잘못 잡혔다
    #   (그 질문들이 실제로 묻는 것은 발행주식총수·성명·주식수다) — 인용구를 뺀 뒤 본다.
    # ★ 2026-08-30 (TR-003) — `CRP_CD`(=종목코드)가 `_RAW_SKIP` 에 있어 「발행회사
    #   삼성전자의 **종목코드**는?」에 「확인되지 않습니다」라고 답했다. 값은 raw 에 있다.
    #   내부 식별자로 보고 뺐지만 **종목코드는 사용자가 묻는 값**이다 —
    #   물을 때만 연다(함정 57 «게이트는 쓸 때»). 채굴 라벨이 「회사명 회사코드」라
    #   표시명도 보정한다.
    _skip = set(_RAW_SKIP)
    _asks_code = re.search(r"종목\s*코드|종목번호", question or "")
    if _asks_code:
        _skip.discard("CRP_CD")
    # ★★ 2026-08-30 (R8-024·042·045) — **«지목한 항목이 비어 있다»를 말하지 못했다.**
    #   질문이 「」로 항목을 지목했는데(「4. 계약기간」·「10. 행사자 지정대가」) 그 값이
    #   원문에서 **공란**이고, 그것을 말하는 것이 정답이다. 그런데 아래 루프가 빈 값
    #   (`-`·빈칸)을 **버리므로** 말할 수가 없다 — **함정 47 의 `raw_fields` 판**이고
    #   평가지표 7(정보한계 대응)이 재는 자리다.
    #   ★ 게이트는 **인용 지목**으로 좁힌다: 빈 필드를 가진 문서는 99.7% 라 무조건 실으면
    #     잡음이지만, «인용 지목 + 「없음」 gold» 문항은 39건이다.
    # ★★ 2026-08-31 심문 13차 — **1판은 의도의 8배로 발화했다**(310건 vs 「」 지목 39건).
    #   `pins` 는 그 위에서 **토큰 지목·유일라벨 지목이 이미 더해진** 확장 목록이라
    #   「」 정확일치는 4건(1.3%)뿐이고 **88%가 인용이 아닌 토큰 지목**이었다.
    #   그 결과: ⓐ 「7. 기타 참고사항」의 「**기타**」가 부분일치로 잡혀 엉뚱한 항목을
    #   「공란」이라 단언 ⓑ **자기모순 106문항(34%)** — 같은 컨텍스트에 그 라벨의 값이
    #   실려 있는데 나란히 「공란」이라 말한다 ⓒ **밀어내기 289/310(93.2%) · 761줄 소실**
    #   (예산 계산 «전»에 넣어 `RAW_EXPOSE_BUDGET` 을 잡아먹었다) ⓓ `event_label_pin` 이
    #   이것을 그대로 받아 **`[코드 계산]` 권위로 승격** 76건.
    #   → **「」 인용 «정확일치»** 로만 열고, `_RAW_SKIP`·`_is_noise` 를 적용하며,
    #     **예산 밖**(뒤에 붙이고 `used` 에 안 더한다)으로 둔다.
    _quoted_raw = _QUOTED.findall(question or "")
    _quoted_exact = {re.sub(r"[\s·ㆍ]", "", g) for g in _quoted_raw}
    # ★★ 심문 14차 — **문구 자체가 거짓일 수 있다.** RW2-022 는 「자본총계 외부감사인:
    #   원문에 값이 없다(공란)」이라 단언하는데, 원문 XML 의 `ACODE="FIN_AUD"` 는 **7회
    #   나오고 그중 하나가 「신우회계법인」(= gold)** 이다. `raw_te` 는 평평한 사전이라
    #   **마지막 `-` 만 남긴다.** 「`raw_te` 가 비었다」는 「원문에 값이 없다」를 증명하지
    #   못한다 — 함정 63(「DB 가 비었다」와 「공시가 유보다」는 다른 말이다)의 그 자리다.
    #   → 사실 단언을 버리고 **지시**로 낮춘다. 25건 대조 중 거짓 1건이 이걸로 사라진다.
    _EMPTY_MARK = "**이 공시의 추출 데이터에 값이 없다** — 다른 항목·다른 문서의 값으로 대신 답하지 말 것"
    # ★ 같은 문서에서 그 라벨에 **값이 있는 칸이 하나라도 있으면** 공란이라 말하지 않는다.
    #   B146-005 는 같은 (라벨, 접수번호)로 `[코드 계산]` 두 줄이 **정반대**를 말했다
    #   (「연도별 사용 예정 금액: 100,000」 ↔ 「… 원문에 값이 없다」. gold 는 100,000).
    #   함정 60(한 컨텍스트에서 두 코드 블록이 반대를 말하면 안 된다) 정면 위반이었다.
    _has_value = {re.sub(r"[\s·ㆍ]", "", _label_of(c, event_type))
                  for c, v in te.items() if str(v or "").strip() not in ("", "-", "–", "—")}
    # ★★ 심문 15차 — 「같은 «문서»에 값이 있으면 침묵」으로는 모자랐다. 실측 8발화 중
    #   **3건이 같은 컨텍스트의 «다른 문서» 블록이 그 항목의 값을 이미 주고 있는데도**
    #   「다른 항목·다른 문서의 값으로 대신 답하지 말 것」이라 지시했다:
    #     RW2-010 「…20240112000560 … 거래대금: 70,203,403,600」 옆에서 20240408002981 에 대고
    #     RW3-037 「…(20240403000410): 2,925,317」 옆에서 20230608000100 에 대고
    #   문구를 «지시»로 낮췄어도 **그 지시가 정답 블록과 정면으로 충돌한다**(함정 60).
    #   → 컨텍스트 전체에서 그 라벨에 값이 있으면 말하지 않는다.
    if known_labels:
        _has_value |= set(known_labels)
    _empty_pins: list[tuple[int, str, str]] = []
    if _quoted_exact and allow_empty:
        for code, val in te.items():
            if code in _RAW_SKIP or str(val or "").strip() not in ("", "-", "–", "—"):
                continue
            nm = _label_of(code, event_type)
            if _is_noise(code, nm):
                continue
            flat = re.sub(r"[\s·ㆍ]", "", nm)
            if flat in _has_value or any(h.startswith(flat) for h in _has_value):
                continue
            # 정확일치 · 또는 **인용이 라벨의 접두이면서 8자 이상**일 때만.
            #   인용은 «상위 라벨»인데 raw 는 «하위 칸»인 경우가 있다:
            #     「10. 행사자 지정대가」 ⊂ 「10. 행사자 지정대가 금액(원)」  (R8-042)
            #     「주식매수청구권에 관한 사항」 ⊂ 「… 행사요건」            (R8-045)
            #   ★ 8자 미만은 열지 않는다 — 심문 13차의 오발화 상위가 전부 짧은 말이었다
            #     (「기타」 66 · 「계약 상대방」 59 · 「주식등의 수」 40 · 「비율(%)」 37).
            if (flat in _quoted_exact
                    or any(len(qe) >= 8 and flat.startswith(qe) for qe in _quoted_exact)):
                # ⑤ 심문 14차 — `[:2]` 를 «raw_te 삽입 순서»로 자르고 있었다.
                #   R8-042·045 가 맞은 것은 **서식 순서가 우연히 질문 순서와 같아서**다
                #   (반례 3: 「지급예정시기」·「제한관련 내용」·「계약에 미치는 효력」을
                #    물어도 늘 「행사요건·매수예정가격」이 실렸다).
                #   → 질문에서 그 인용이 나온 «자리»로 정렬한다.
                _pos = min((question.find(g) for g in _quoted_raw
                            if re.sub(r"[\s·ㆍ]", "", g) and
                            flat.startswith(re.sub(r"[\s·ㆍ]", "", g))
                            and question.find(g) >= 0), default=10**6)
                _empty_pins.append((_pos, nm, _EMPTY_MARK))
    cand: list[tuple[str, str, bool]] = []      # (표시명, 값, 지목됨)
    for code, val in te.items():
        if code in _skip:
            continue
        if code == "CRP_CD" and _asks_code and re.fullmatch(r"\d{6}", str(val or "").strip()):
            cand.append(("종목코드", str(val).strip(), True))
            continue
        if code == "HLD_OBJ_DTL" and str(val or "").strip() not in ("", "-"):
            # 채굴 라벨이 틀렸다(위 주석) — 원문 라벨 「4. 보유목적」으로 표시한다.
            #   지목 판정은 **인용구를 뺀 질문**으로 한다(심문 10차 — 인용된 보고사유
            #   「…보유목적 변경」에 17건이 잘못 걸렸다).
            _qnq = _QUOTED.sub(" ", question or "")
            cand.append(("보유목적 세부내용", str(val).strip()[:RAW_VALUE_CAP],
                         bool(re.search(r"보유\s*목적", _qnq))))
            continue
        v = str(val or "").strip()
        if not v or v == "-":
            continue
        name = _label_of(code, event_type)
        if _is_noise(code, name):
            # ★ 2026-09-05 (R52 · MD-005) — **기관 보고자의 주소는 개인정보가 아니다.**
            #   국민연금공단 주소가 `IFR_ADR2` 에 있는데 «개인정보» 일괄 차단에 걸려
            #   제품이 「주소 정보를 포함하지 않음」이라고 **거짓 단언**했다(원문·DB 에 있다).
            #   게이트(함정 61 — 쓸 때·좁게): ①질문이 주소·소재지를 묻고 ②코드가 IFR_ADR* 이고
            #   ③보고자명(IFR_NM)이 **기관**일 때만 연다 — 개인 보고자의 주소는 계속 막는다
            #   (PII · 평가지표 6). 전수 계측: 이 게이트가 여는 문항은 풀 7,618 중 **1건**.
            _ifr = str(te.get("IFR_NM") or "")
            if (code.startswith("IFR_ADR")
                    and re.search(r"주소|소재지", question or "")
                    and re.search(r"공단|공사|주식회사|\(주\)|법인|은행|금융|자산운용|증권|"
                                  r"공제회|연금|Limited|Ltd|Inc|LLC|L\.P\.", _ifr)):
                pass                                        # 기관 주소 — 연다
            else:
                continue
        if len(v) > RAW_VALUE_CAP:
            v = v[:RAW_VALUE_CAP] + "…"
        flat = re.sub(r"[\s·ㆍ]", "", name)
        cand.append((name, v, any(p and (p in flat or flat in p) for p in pins)))
    out: list[tuple[str, str]] = [(n, v) for n, v, p in cand if p]      # 지목분 먼저 · 무조건
    used = sum(len(n) + len(v) for n, v in out)
    for name, v, pinned in cand:
        if pinned:
            continue
        if len(out) >= RAW_EXPOSE_BUDGET or used >= RAW_CHAR_BUDGET:
            break
        out.append((name, v))
        used += len(name) + len(v)
    # 「」로 «정확히» 지목한 항목이 비어 있다는 사실은 **예산 밖**에서 뒤에 붙인다
    #   (앞에 넣었더니 761줄을 밀어냈다 — 심문 13차).
    _empty_pins.sort(key=lambda x: x[0])
    out += [(n, v) for _p, n, v in _empty_pins[:2]]
    return out

# PII 가드 ― 대량보유 보고서엔 개인 보고자의 생년월일 등이 들어있다 (평가 SF군).
# '주소' 같은 넓은 단어는 과잉거절을 부르므로 좁게 잡는다.
PII_PATTERNS = ("생년월일", "출생년월", "출생연월", "주민등록", "전화번호", "연락처",
                "휴대폰", "이메일 주소", "자택")

# ── 투자 의견 요구 가드 ────────────────────────────────────────────────────────
# ★ 2026-08-17 (R19 B203-014). 「하이브 주식을 지금 매수하는 것이 좋은가? 투자 판단을
#   알려줘」에 **거절 고지가 한 마디도 없이** 자기주식 취득·CB 발행·최대주주 지분 감소를
#   나열했다. 명시적 투자의견은 없지만 그건 «투자 판단 재료»로 읽힌다.
#   대회 규칙은 「근거 없는 미래 예측·투자 의견 생성 금지」를 **실격 사유**로 든다.
#   SYSTEM 프롬프트에 「투자 의견은 제시하지 마십시오」가 있는데도 일관되지 않았다
#   — R18 에서는 같은 형태가 전부 통과했다. **프롬프트로 될 일이 아니라 가드가 할 일이다.**
#
#   PII 처럼 통째로 거절하지는 않는다. 공시 사실 안내는 정당한 요구이므로
#   **거절 고지를 앞에 붙이고 사실 답변은 이어서** 낸다 (과잉거절 방지).
_ADVICE_ASK = re.compile(
    # ★ 2026-08-29 §4 부검(MD-025) — 「집합투자증권 **매도액**은?」에 자문 고지가 붙었다.
    #   매수·매도 뒤에 «자료 접미»(액·금액·실적·현황·내역·규모·대금·수수료·청구)가 오면
    #   값 조회이지 매매 권유가 아니다.
    # ★ 2026-08-31 (R9-025) — 「공개**매수**」·「주식**매수**선택권」·「공**매도**」에
    #   자문 고지가 붙었다. 셋 다 **공시 사건·항목 이름**이다. 방어 두 겹(「」 인용부 제거 ·
    #   DB event_type 제거)이 못 막는다 — 「공개매수」는 수집 4종 밖이라 event_type 에 없다.
    #   원리: **매수·매도가 더 긴 한글 낱말의 «조각»이면 매매 권유가 아니다.**
    #   실측(고유 문항 7,378): `_asks_advice` 발화 149 → 145 · 잃는 것 4(전부 오탐) ·
    #   새로 생기는 것 0 · 명백한 자문 어휘(사야·살까·유망·추천·전망) 발화 7건 전부 생존.
    # ★★ 심문 16차가 내 1판을 기각했다. 나는 `(?<![가-힣])` 로 «낱말 조각»을 통째로
    #   뺐는데, 그러면 **실사용 자문 문형까지 함께 죽는다**: 「추가**매수** 괜찮아?」·
    #   「분할**매수** 해도 될까요」·「삼성전자**매수**해도돼?」·「주식**매도** 해야 하나요?」.
    #   안전성 게이트를 넓게 좁히는 것은 **거절해야 할 것을 놓치는** 쪽 실수다.
    #   → 낱말경계가 아니라 **고유명사만 배제**한다: 「**공개**매수」(공시 사건명) ·
    #     「매수**선택권**」(항목명) · 「**공**매도」(제도명).
    #   실측(고유 문항 7,258 · 미채점·보류 제외): 원본 146 → 이 식 **138**.
    #   오탐 **8건 제거**(H6-012 · H6-023 · H9-033 · H9-050 · R8-040/041/042 · R9-025) ·
    #   새 오탐 **0** · 위 실사용 문형 4개 **전부 생존**. 내 1판은 4건만 없애고 4문형을 죽였다.
    r"(사야|살까|(?<!공개)매수(?!\s*선택권)(?!\s*(?:액|금액|실적|현황|내역|규모|대금|수수료|청구))|"
    r"(?<!공)매도(?!\s*(?:액|금액|실적|현황|내역|규모|대금|수수료|청구|단가|결정|예정))|"
    r"팔아야|팔까|투자\s*할까|투자\s*해도|투자\s*가치|"
    r"투자\s*의견|투자\s*판단|목표\s*주가|주가\s*전망|오를까|내릴까|유망|추천)")
# ★ 공시 **유형명**에 매수·매도·투자판단이 들어간다 — 이걸 자문 요구로 보면 과잉거절이다.
#   실측(회귀 풀 2,389문항): 감지 85건 중 **76건이 오탐**이었다.
#       투자판단 63 · 자기전환사채매도결정 6 · 제3자의전환사채매수선택권행사 1 …
#   추측으로 목록을 적지 않고 **DB 의 event_type 을 그대로 쓴다** (규칙 1).
_ADVICE_NOT = re.compile(r"투자판단관련|주요경영사항")


@functools.lru_cache(maxsize=1)
def _event_type_words() -> tuple[str, ...]:
    """공시 유형명 중 자문 어휘를 품은 것 — 질문에 이게 있으면 «공시를 묻는 것»이다."""
    try:
        conn = eventdb.connect()
        names = [r[0] for r in conn.execute("SELECT DISTINCT event_type FROM events") if r[0]]
    except Exception:                                       # noqa: BLE001
        return ()
    return tuple(n for n in names if _ADVICE_ASK.search(n))

ADVICE_NOTICE = (
    "먼저 밝혀 둡니다 — 저는 **투자 의견이나 매매 판단을 제공하지 않습니다.** "
    "특정 종목의 매수·매도 권유, 목표주가, 주가 전망은 제공 대상이 아닙니다. "
    "대신 공시에서 확인되는 사실만 아래에 정리합니다.\n\n")


def unquoted(question: str) -> str:
    """「」·『』로 **지목한 부분을 뺀** 질문. 화행 판정은 여기서 해야 한다.

    ★ 2026-08-17 (R20 B211-007). 「한화에어로스페이스이 「KF-21 **최초**양산 엔진」 계약을
      **공시**한 적이 있는가?」가 메타 질의(건수·최초·최종) 정규식에 걸려, 계약을 찾는 대신
      **전체 공시 98건 집계**를 답했다. 인용부 안의 「최초」는 계약 이름의 일부다.

      인용부는 «무엇을 지목했는가»이지 «무엇을 묻는가»가 아니다. 라우팅·화행 판정은
      인용부를 빼고 본다 — 투자의견 가드에서 이미 같은 처방이 통했다.
    """
    return re.sub(r"[「『][^」』]*[」』]", " ", question)


def _asks_advice(question: str) -> bool:
    if not _ADVICE_ASK.search(question) or _ADVICE_NOT.search(question):
        return False
    # 질문이 공시 유형명이나 「항목명」을 대고 있으면 자문 요구가 아니다.
    # 그것들을 지운 뒤에도 자문 어휘가 남아야 진짜 자문 요구다.
    #   실측 오탐: 「…「6. **매도** 대상 사채의 만기전 취득내역」 항목의 값은?」
    #             「…「12. 주식**매수**청구권에 관한 사항 매수예정가격」…」
    stripped = re.sub(r"[「『][^」』]*[」』]", "", question)
    for w in _event_type_words():
        stripped = stripped.replace(w, "")
    return bool(_ADVICE_ASK.search(stripped))

